from pathlib import Path
p=Path('index.html')
s=p.read_text()
marker='MOLMS-FINANCE-CARRYFORWARD-RECEIVABLES-V1'
if marker in s:
    print('already patched'); raise SystemExit
patch=r'''\n<script>\n/* MOLMS-FINANCE-CARRYFORWARD-RECEIVABLES-V1 */\n(function(){\n  function money(n){return Number(n||0).toLocaleString();}\n  function approved(t){return (t.status||'')==='approved'||t.is_approved===true;}\n  function ensureManualReceivableFields(){\n    const amt=document.getElementById('fdManualAmount'); if(!amt||document.getElementById('fdClientReceivableWrap')) return;\n    const wrap=document.createElement('div'); wrap.id='fdClientReceivableWrap'; wrap.style='margin-top:10px;border:1px solid var(--border);border-radius:10px;padding:10px;background:#fafafa';\n    wrap.innerHTML=`<label style="display:flex;gap:8px;align-items:center;font-size:12px;font-weight:700"><input id="fdClientReceivable" type="checkbox" onchange="fdToggleClientReceivable()"> This is a payment against an amount owed by a client</label><div id="fdClientReceivableFields" style="display:none;margin-top:10px;grid-template-columns:1fr 1fr;gap:8px"><input id="fdReceivableClient" class="search" placeholder="Client name"><input id="fdReceivableMatter" class="search" placeholder="Matter / reference (optional)"><input id="fdAgreedAmount" type="number" min="0" step="0.01" class="search" placeholder="Agreed amount"><div id="fdOutstandingPreview" style="padding:8px;font-size:12px;font-weight:700;color:var(--navy)">Outstanding: —</div></div>`;\n    amt.closest('div[style*="grid-template-columns"]')?.after(wrap);\n    amt.addEventListener('input',fdUpdateOutstandingPreview);\n  }\n  window.fdToggleClientReceivable=function(){const on=document.getElementById('fdClientReceivable')?.checked; const f=document.getElementById('fdClientReceivableFields'); if(f)f.style.display=on?'grid':'none'; fdUpdateOutstandingPreview();};\n  window.fdUpdateOutstandingPreview=function(){const agreed=Number(document.getElementById('fdAgreedAmount')?.value||0),received=Number(document.getElementById('fdManualAmount')?.value||0),el=document.getElementById('fdOutstandingPreview'); if(el)el.textContent=agreed>0?'Outstanding: '+money(Math.max(0,agreed-received)):'Outstanding: —';};\n  const oldOpen=window.fdOpenManualModal; if(oldOpen) window.fdOpenManualModal=function(){const r=oldOpen.apply(this,arguments); setTimeout(()=>{ensureManualReceivableFields(); const c=document.getElementById('fdClientReceivable'); if(c)c.checked=false; fdToggleClientReceivable();},0); return r;};\n  const oldEdit=window.fdEditManual; if(oldEdit) window.fdEditManual=async function(id){await oldEdit.apply(this,arguments); ensureManualReceivableFields(); const t=(_fdAllManual||[]).find(x=>x.id===id); if(t){document.getElementById('fdClientReceivable').checked=!!t.client_receivable; document.getElementById('fdReceivableClient').value=t.receivable_client_name||t.counterparty||''; document.getElementById('fdReceivableMatter').value=t.receivable_matter_ref||''; document.getElementById('fdAgreedAmount').value=t.agreed_amount||''; fdToggleClientReceivable();}};\n  const oldSave=window.fdSaveManual; if(oldSave) window.fdSaveManual=async function(){\n    const on=!!document.getElementById('fdClientReceivable')?.checked;\n    if(!on) return oldSave.apply(this,arguments);\n    const amount=Number(document.getElementById('fdManualAmount')?.value||0),agreed=Number(document.getElementById('fdAgreedAmount')?.value||0),client=(document.getElementById('fdReceivableClient')?.value||document.getElementById('fdManualCounterparty')?.value||'').trim();\n    if(!client||agreed<=0||amount<=0||amount>agreed){notice('For a client receivable, enter the client, agreed amount and amount received. Amount received cannot exceed the agreed amount.','err');return;}\n    const editId=document.getElementById('fdManualId')?.value||null;\n    await oldSave.apply(this,arguments);\n    let q=sb.from('fd_manual_transactions').select('id').eq('client_receivable',false).eq('amount',amount).order('created_at',{ascending:false}).limit(1);\n    if(editId) q=sb.from('fd_manual_transactions').select('id').eq('id',editId);\n    const {data}=await q.maybeSingle(); if(data?.id){await sb.from('fd_manual_transactions').update({client_receivable:true,agreed_amount:agreed,outstanding_amount:Math.max(0,agreed-amount),receivable_client_name:client,receivable_matter_ref:(document.getElementById('fdReceivableMatter')?.value||'').trim()||null}).eq('id',data.id); await fdRefresh();}\n  };\n  window.fdCarryForwardSnapshot=function(){\n    const start=new Date((_fdPeriodStart||new Date()).toString()), startISO=start.toISOString().slice(0,10);\n    const priorInv=(_fdAllInvoices||[]).filter(i=>i.invoice_type==='tax'&&i.invoice_date<startISO&&!['void','cancelled','draft'].includes(i.status));\n    const priorManual=(_fdAllManual||[]).filter(t=>t.date<startISO&&approved(t));\n    const cashIn=priorManual.filter(t=>['revenue','loan'].includes(t.tx_type)).reduce((s,t)=>s+Number(t.amount||0),0)+(_fdAllInvoices||[]).flatMap(fdInvoiceCashReceipts).filter(r=>r.date<startISO).reduce((s,r)=>s+Number(r.amount||0),0);\n    const cashOut=priorManual.filter(t=>['expenditure','drawing'].includes(t.tx_type)).reduce((s,t)=>s+Number(t.amount||0),0);\n    const invRec=priorInv.reduce((s,i)=>s+Math.max(0,Number(i.total_due||0)-Number(i.amount_paid||0)-Number(i.withholding_tax_amount||0)),0);\n    const manualRec=(_fdAllManual||[]).filter(t=>approved(t)&&t.client_receivable).reduce((s,t)=>s+Number(t.outstanding_amount||0),0);\n    return {openingCash:cashIn-cashOut,receivables:invRec+manualRec};\n  };\n  window.fdRenderReceivablesCard=function(){\n    const host=document.getElementById('fdReceivablesCardV1')||document.createElement('div'); host.id='fdReceivablesCardV1'; host.className='card'; host.style='margin-top:12px;padding:14px';\n    const rows={};\n    (_fdAllInvoices||[]).filter(i=>i.invoice_type==='tax'&&!['void','cancelled','draft','paid'].includes(i.status)).forEach(i=>{const b=Math.max(0,Number(i.total_due||0)-Number(i.amount_paid||0)-Number(i.withholding_tax_amount||0));if(b>0){const k=i.client_name||'Unnamed client';rows[k]=(rows[k]||0)+b;}});\n    (_fdAllManual||[]).filter(t=>approved(t)&&t.client_receivable&&Number(t.outstanding_amount||0)>0).forEach(t=>{const k=t.receivable_client_name||t.counterparty||'Unnamed client';rows[k]=(rows[k]||0)+Number(t.outstanding_amount||0);});\n    const list=Object.entries(rows).sort((a,b)=>b[1]-a[1]),total=list.reduce((s,x)=>s+x[1],0);\n    host.innerHTML=`<div style="display:flex;justify-content:space-between;align-items:center"><div><div style="font-size:11px;color:var(--muted);font-weight:800;text-transform:uppercase">Receivables</div><div style="font-size:22px;font-weight:800;color:var(--navy)">TZS ${money(total)}</div></div><div style="font-size:11px;color:var(--muted)">Who owes the firm</div></div><div style="margin-top:8px">${list.slice(0,5).map(([n,v])=>`<div style="display:flex;justify-content:space-between;padding:5px 0;border-top:1px solid var(--border);font-size:12px"><span>${esc(n)}</span><strong>TZS ${money(v)}</strong></div>`).join('')||'<div style="font-size:12px;color:var(--muted);padding-top:8px">No open receivables.</div>'}</div>`;\n    const target=document.getElementById('fdDashboard')||document.querySelector('#findash .content')||document.querySelector('#findash'); if(target&&!host.parentNode)target.appendChild(host);\n  };\n  const oldRender=window.fdRender; if(oldRender) window.fdRender=async function(){const r=await oldRender.apply(this,arguments); try{fdRenderReceivablesCard();}catch(e){console.warn(e)} return r;};\n  document.addEventListener('DOMContentLoaded',ensureManualReceivableFields);\n})();\n</script>\n'''
pos=s.lower().rfind('</body>')
if pos<0: raise SystemExit('no body')
s=s[:pos]+patch+s[pos:]
p.write_text(s)
print('patched')
